fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // For arrays of length 0 or 1, return as-is.
    if n <= 1 {
        return numbers;
    }

    // Prepare a result vector of the exact required capacity: 2*n - 1.
    let mut result = Vec::with_capacity(2 * n - 1);

    // Consume the input vector, pushing each element and, if it's not
    // the last element, the delimiter afterward.
    for (i, num) in numbers.into_iter().enumerate() {
        result.push(num);
        if i + 1 != n {
            result.push(delimiter);
        }
    }

    result
}

